<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait TemplateAssetTenantAttributeHolder
{
    protected TemplateAssetTenantVO|TenantRef|null $tenant = null;
    protected bool $tenantAssigned = false;

    public function getTenantOrDefault(TemplateAssetTenantVO $tenant): TemplateAssetTenantVO
    {
        if ($this->tenantAssigned) {
            \assert(null !== $this->tenant);
            return TemplateAssetTenantVO::from($this->tenant);
        } else {
            return $tenant;
        }
    }
    public function tenant(TemplateAssetTenantVO|TenantRef $tenant): static
    {
        $this->tenant = $tenant;
        $this->tenantAssigned = true;
        return $this;
    }
    public function getTenant(): ?TenantRef
    {
        return $this->tenant instanceof TemplateAssetTenantVO ? $this->tenant->value() : $this->tenant;
    }
    public function isTenantAssigned(): bool
    {
        return $this->tenantAssigned;
    }
    public function writeTenantTo(mixed $att): void
    {
        if ($this->tenantAssigned) {
            \assert(null !== $this->tenant);
            $att->tenant($this->tenant);
        }
    }
    public function readTenantFrom(mixed $att): void
    {
        if ($att->isTenantAssigned()) {
            $tenant = $att->getTenant();
            \assert(null !== $tenant);
            $this->tenant($tenant);
        }
    }
    public function unsetTenant(): static
    {
        $this->tenantAssigned = false;
        return $this;
    }
    protected function withDefaultTenant(): void
    {
    }
    protected function withAssertedTenantRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->tenantAssigned = $this->tenantAssigned) {
            $value->tenant = TemplateAssetTenantVO::tryFrom($this->tenant, $errorsList);
        }
    }
}
